'use strict';
let gcBenchTab='reaction';try{gcBenchTab=localStorage.getItem('simlab-bench-tab')==='gc'?'gc':'reaction'}catch{}
const GC_SOLVENTS=[{id:'water',name:'Water'},{id:'methanol',name:'Methanol'},{id:'ethanol',name:'Ethanol'},{id:'propanol',name:'1-Propanol'},{id:'isopropanol',name:'2-Propanol / isopropanol'},{id:'acetonitrile',name:'Acetonitrile'},{id:'acetone',name:'Acetone'},{id:'hexane',name:'n-Hexane'},{id:'heptane',name:'n-Heptane'},{id:'toluene',name:'Toluene'},{id:'ethylAcetate',name:'Ethyl acetate'},{id:'dichloromethane',name:'Dichloromethane'},{id:'cyclohexane',name:'Cyclohexane'}];
const gseq={queue:[],next:1,active:false,current:null,launching:false,timer:null,message:'Export prepared vials from Open bench to populate the sample rack.',open:false};
try{const saved=JSON.parse(localStorage.getItem('simlab-gc-sequence')||'null');if(saved&&Array.isArray(saved.queue)){gseq.queue=saved.queue.filter(e=>gcal.vials.some(v=>v.id===e.vial)).map(e=>({...e,status:['running','equilibrating'].includes(e.status)?'Interrupted':e.status}));gseq.next=Math.max(0,...gseq.queue.map(e=>e.id))+1;}}catch{}
gcal.form.solvent??='water';gcal.form.label??='';
function gcPrepEsc(x){return String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;')}
function gcVialLabel(v){return v.label||`${v.role==='standard'?'Standard':v.role==='blank'?'Blank':'Unknown'} ${v.id}`}
function gcVialSolvent(v){return GC_SOLVENTS.find(s=>s.id===(v.solvent||'water'))?.name||'Water'}
function gcSequenceSave(){try{localStorage.setItem('simlab-gc-sequence',JSON.stringify({queue:gseq.queue,next:gseq.next}))}catch{}}
function gcCalRefresh(){gcCalSave();gcSequenceSave();if(typeof page!=='undefined'&&['bench','instrumentation'].includes(page))render()}
function gcBenchTabs(){return `<div class="gc-bench-tabs" role="tablist" aria-label="Open bench workspace"><button role="tab" aria-selected="${gcBenchTab==='reaction'}" class="btn ${gcBenchTab==='reaction'?'':'secondary'}" data-gprep-tab="reaction">Reaction bench</button><button role="tab" aria-selected="${gcBenchTab==='gc'}" class="btn ${gcBenchTab==='gc'?'':'secondary'}" data-gprep-tab="gc">GC sample preparation</button></div>`}
function gcPrepOptions(selected){return GC_COMPOUNDS.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${c.name}</option>`).join('')}
function gcPreparationPanel(){if(typeof gmx!=='undefined'&&gmx.tab==='mixtures')return gcMixturePanel();const internal=gcal.mode==='internal',fixed=gcal.vials.length>0,locked=gcLocked()||gseq.active;return `${typeof gcMixtureTabs==='function'?gcMixtureTabs():''}<section class="panel gc-panel gprep"><div class="gc-titlebar"><div><span class="eyebrow">OPEN BENCH · GC SAMPLE PREPARATION</span><h2>Prepare, dilute and label your vials</h2></div><button class="btn secondary" data-gprep-action="instrument">Go to GC →</button></div><p>Prepare standards or practice samples in a volumetric flask, transfer to labelled vials, then export them to the GC sample rack. Concentrations use <b>mg/mL</b>.</p><div class="gcal-setup"><label class="gc-field">Calibration method<select data-gcal-config="mode" ${fixed||locked?'disabled':''}><option value="external" ${!internal?'selected':''}>External standard</option><option value="internal" ${internal?'selected':''}>Internal standard</option></select></label><label class="gc-field">Analyte / calibration standard<select data-gcal-config="analyte" ${fixed||locked?'disabled':''}>${gcPrepOptions(gcal.analyte)}</select></label>${internal?`<label class="gc-field">Internal standard<select data-gcal-config="is" ${fixed||locked?'disabled':''}>${gcPrepOptions(gcal.is)}</select></label>`:''}</div><p>${internal?'Add a known amount of a different, resolved compound as the internal standard. It must be absent from the original sample.':'Use several known analyte concentrations to relate peak area to concentration.'} The method and compounds are fixed once vials are prepared.</p><div class="gc-actions"><button class="btn secondary small" data-gcal-action="new" ${locked?'disabled':''}>New calibration · clear vials & data</button><button class="btn secondary small" data-gcal-action="example" ${locked?'disabled':''}>Prepare five example levels</button></div><div class="gprep-grid"><div class="gprep-form"><h3>1 · Measure and dilute</h3><div class="gc-two"><label class="gc-field">Vial label (optional)<input maxlength="60" data-gprep-text="label" value="${gcPrepEsc(gcal.form.label)}" placeholder="e.g. Ethanol level 1" ${locked?'disabled':''}></label><label class="gc-field">Vial role<select data-gcal-config="role" ${locked?'disabled':''}><option value="standard" ${gcal.form.role==='standard'?'selected':''}>Calibration standard</option><option value="unknown" ${gcal.form.role==='unknown'?'selected':''}>Practice unknown</option><option value="blank" ${gcal.form.role==='blank'?'selected':''}>Solvent blank</option></select></label><label class="gc-field">Diluent / solvent<select data-gprep-solvent ${locked?'disabled':''}>${GC_SOLVENTS.map(s=>`<option value="${s.id}" ${gcal.form.solvent===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label>${gcCalInput('Final solution volume / mL','final')}${gcal.form.role!=='blank'?gcCalInput(gcal.form.role==='unknown'?'Sample stock / mg mL⁻¹ (simulator setup)':'Analyte stock / mg mL⁻¹','stock')+gcCalInput('Analyte / sample aliquot / mL','aliquot')+(internal?gcCalInput('Internal-standard stock / mg mL⁻¹','isStock')+gcCalInput('Internal-standard aliquot / mL','isVolume'):''):''}</div><button class="btn" data-gcal-action="prepare" ${locked?'disabled':''}>Prepare vial</button></div><div class="gprep-scene"><h3>2 · Make up to volume, mix and vial</h3><svg viewBox="0 0 480 245" role="img" aria-label="Stock solution transferred by pipette into a volumetric flask, diluted to its mark, then placed in a labelled GC vial"><rect x="25" y="75" width="74" height="125" rx="10" fill="#dff4eb" stroke="#6c9c8b" stroke-width="2"/><rect x="39" y="55" width="46" height="23" rx="4" fill="#416d5e"/><text x="62" y="127" text-anchor="middle">Stock</text><path d="M115 105h55m-10-8 10 8-10 8" stroke="#087e67" fill="none" stroke-width="2"/><path d="M226 35h28v81l49 72q10 23-15 23h-95q-25 0-15-23l48-72Z" fill="#edf7f1" stroke="#6c9c8b" stroke-width="2"/><path d="M190 173h100l13 15q10 23-15 23h-95q-25 0-15-23Z" fill="#a7d8c8"/><path d="M220 79h40" stroke="#bd7541" stroke-width="3"/><text x="276" y="70">Final volume</text><path d="M320 155h45m-10-8 10 8-10 8" stroke="#087e67" fill="none" stroke-width="2"/><rect x="390" y="123" width="50" height="83" rx="8" fill="#dcf0e7" stroke="#6c9c8b" stroke-width="2"/><rect x="389" y="111" width="52" height="17" rx="3" fill="#416d5e"/><rect x="397" y="150" width="36" height="30" fill="white"/><text x="415" y="169" text-anchor="middle">GC</text></svg><p>Transfer measured stock and internal-standard aliquots, then add ${gcPrepEsc(GC_SOLVENTS.find(s=>s.id===gcal.form.solvent)?.name||'solvent')} <b>to the final volume</b>, rather than adding that much solvent.</p><div class="gc-notice">C vial = C stock × V aliquot / V final${internal?'<br>C IS = C IS stock × V IS / V final':''}</div><p>Solvent choice is retained in each vial’s preparation record. This teaching model assumes a homogeneous, soluble sample and omits the solvent peak; solvent-dependent retention, solubility and inlet expansion are not simulated. Choose a diluent different from the analyte and internal standard.</p></div></div><div class="gc-notice" role="status">${gcPrepEsc(gcal.message)}</div><div class="gc-titlebar"><h3>3 · Prepared vial rack</h3><button class="btn secondary small" data-gprep-action="export-all" ${locked||!gcal.vials.length?'disabled':''}>Export all to GC</button></div>${gcPreparedRack()}<details class="gc-detail"><summary>Preparation notes and organic solvent library</summary><p>For unknowns, entered stock concentration defines the simulated sample. Reported concentration is calculated from measured chromatographic response and the calibration, with the aliquot dilution reversed. Blanks contain only the selected solvent. Methanol, ethanol, 1-propanol, 2-propanol, acetonitrile, acetone, hexane, heptane, toluene, ethyl acetate, dichloromethane and cyclohexane are available as virtual solvents; the organic reagents are also available in Reaction bench.</p></details></section>`}
function gcPreparedRack(){return `<div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Vial / role</th><th>Analyte</th><th>C vial / mg mL⁻¹</th><th>C IS / mg mL⁻¹</th><th>Solvent</th><th>Preparation / mL</th><th>Transfer</th></tr></thead><tbody>${gcal.vials.map(v=>v.role==='mixture'?gcMixtureRackRow(v):`<tr><td>${gcPrepEsc(gcVialLabel(v))}<br><small>${v.role}</small></td><td>${v.role==='blank'?'—':gcCalName(gcal.analyte)}</td><td>${v.role==='unknown'?'Hidden':gcFmt(v.concentration,4)}</td><td>${gcFmt(v.isC,4)}</td><td>${gcPrepEsc(gcVialSolvent(v))}</td><td>${v.role==='blank'?'Solvent only':`${v.preparation.aliquot} aliquot${v.isC?' + '+v.preparation.isVolume+' IS':''}`} → ${v.preparation.final}</td><td><button class="btn secondary small" data-gprep-export="${v.id}" ${gcLocked()||gseq.active?'disabled':''}>${v.exported?'Exported · add injection':'Export to GC'}</button></td></tr>`).join('')||'<tr><td colspan="7">Prepare your first vial or use the five-level example.</td></tr>'}</tbody></table></div>`}
function gcExportVial(id,repeats=1){const v=gcal.vials.find(v=>v.id===id);if(!v)throw Error('Prepared vial not found.');if(!Number.isInteger(repeats)||repeats<1||repeats>5)throw Error('Choose one to five injections per vial.');if(gseq.queue.length+repeats>60)throw Error('The sequence holds up to 60 injections. Remove finished entries before adding more.');v.exported=true;for(let i=0;i<repeats;i++)gseq.queue.push({id:gseq.next++,vial:id,volume:Number(gc.method.volume),status:'Pending'});gseq.message=gcVialLabel(v)+' exported to the GC rack and queued.';gcal.message=gseq.message;gcCalSave();gcSequenceSave()}
function gcSampleLoader(){const exported=gcal.vials.filter(v=>v.exported);return `<label class="gc-field">Load prepared sample<select id="gcPreparedSample" ${gcLocked()||gseq.active?'disabled':''}><option value="">Choose a bench vial</option>${exported.map(v=>`<option value="${v.id}" ${gcal.loaded===v.id?'selected':''}>${gcPrepEsc(gcVialLabel(v))} · ${v.role} · ${gcPrepEsc(gcVialSolvent(v))}</option>`).join('')}</select></label>${typeof gcNextSamplePanel==='function'?gcNextSamplePanel():''}<div class="gc-actions"><button class="btn small" data-gprep-action="load" ${!exported.length||gcLocked()||gseq.active?'disabled':''}>Load sample</button><button class="btn secondary small" data-gprep-action="sequence-window">Set sequence</button><button class="btn secondary small" data-gprep-action="bench">Prepare at Open bench ↗</button></div><p>${gcal.loaded?gcPrepEsc(gcVialLabel(gcal.vials.find(v=>v.id===gcal.loaded)||{id:gcal.loaded})):exported.length+' prepared vial(s) available.'} · Standards and sample concentrations are prepared at Open bench.</p>`}
function gcSequencePanel(){return `<details class="panel gc-panel gc-sequence" id="gcSequenceWindow" ${gseq.open?'open':''}><summary><b>Sample rack &amp; sequence</b> · ${gseq.queue.filter(e=>e.status==='Pending').length} pending · ${gseq.active?'RUNNING':'click to set up'}</summary><div class="gc-actions"><button class="btn" data-gseq-action="start" ${gcLocked()||gseq.active||!gseq.queue.some(e=>e.status==='Pending')?'disabled':''}>Run sequence</button><button class="btn secondary" data-gseq-action="stop" ${!gseq.active?'disabled':''}>Stop sequence</button><button class="btn secondary small" data-gseq-action="clear" ${gseq.active||gcLocked()?'disabled':''}>Remove finished entries</button><button class="btn secondary small" data-gcal-action="method" ${gseq.active||gcLocked()?'disabled':''}>Load alcohol separation method</button></div><p>Power on, enable carrier, prepare the selected detector before starting. The sequence then loads each queued vial, acquires a complete run and re-equilibrates automatically. For FID quantitation, place at least three distinct standards before an unknown. Repeat injections replace that vial’s calibration point; prepare separate vials for independent replicates.</p><div class="gc-notice" id="gcSequenceMessage" role="status">${gcPrepEsc(gseq.message)}</div><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Order</th><th>Vial</th><th>Role</th><th>Solvent</th><th>Injection / µL</th><th>Status</th><th>Edit</th></tr></thead><tbody>${gseq.queue.map((e,i)=>{const v=gcal.vials.find(v=>v.id===e.vial);return `<tr><td>${i+1}</td><td>${gcPrepEsc(v?gcVialLabel(v):'Missing vial')}</td><td>${v?.role||'—'}</td><td>${v?gcPrepEsc(gcVialSolvent(v)):'—'}</td><td><input class="gseq-volume" aria-label="Injection volume for sequence row ${i+1}" data-gseq-volume="${e.id}" type="number" min="0.1" max="5" step="0.1" value="${e.volume}" ${gseq.active||e.status!=='Pending'?'disabled':''}></td><td>${gcPrepEsc(e.status)}</td><td><button class="btn secondary small" data-gseq-up="${e.id}" ${gseq.active||i===0?'disabled':''} aria-label="Move sequence row ${i+1} up">↑</button> <button class="btn secondary small" data-gseq-remove="${e.id}" ${gseq.active?'disabled':''}>Remove</button> <button class="btn secondary small" data-gseq-repeat="${e.id}" ${gseq.active?'disabled':''}>Repeat</button></td></tr>`}).join('')||'<tr><td colspan="7">No queued vials. Prepare and export samples from Open bench.</td></tr>'}</tbody></table></div></details>`}
function gcSequenceValidate(){const pending=gseq.queue.filter(e=>e.status==='Pending');if(!pending.length)throw Error('No pending injections.');if(!gc.power||!gc.carrier||!gc.ready||!gcDetectorReady())throw Error('Power on, enable carrier gas, prepare the selected detector first.');const levels=new Set(gcal.points.map(p=>p.x));let key=gcal.method;for(const e of pending){const v=gcal.vials.find(v=>v.id===e.vial);if(!v)throw Error('A queued vial is missing.');const m={...gc.method,volume:e.volume},errors=gcValidation(m);if(errors.length)throw Error(errors.join(' '));if(!gcIsMS(m)&&!['blank','mixture'].includes(v.role)){const k=gcCalKey(m);if(key&&key!==k)throw Error('Queued methods must match the calibration. For external calibration use the same injection volume.');key??=k;}if(v.role==='standard')levels.add(gcal.mode==='internal'?v.concentration/v.isC:v.concentration);if(!gcIsMS(m)&&v.role==='unknown'&&levels.size<3)throw Error('Move at least three distinct standards before the unknown.');}return pending}
function gcSequenceStart(){if(gseq.active||gcLocked())return;try{gcSequenceValidate();gseq.active=true;gseq.message='Sequence started. The first prepared sample is being loaded.';gcSequenceNext(true)}catch(e){gseq.message=e.message;gcCalRefresh()}}
function gcSequenceNext(first=false){if(!gseq.active)return;const e=gseq.queue.find(e=>e.status==='Pending');if(!e){gseq.active=false;gseq.current=null;gseq.message='Sequence complete. Review run measurements in the notebook and the calibration results below.';gcCalRefresh();return}gseq.current=e.id;gcCalLoad(e.vial);gc.method.volume=e.volume;gseq.message='Injection '+(gseq.queue.indexOf(e)+1)+' · '+gcVialLabel(gcal.vials.find(v=>v.id===e.vial));const launch=()=>{if(!gseq.active)return;e.status='Running';gseq.launching=true;const ok=gcStart();gseq.launching=false;if(!ok){e.status='Failed';gseq.active=false;gseq.message=gc.message;}else gc.run.sequenceEntry=e.id;gcCalRefresh()};if(first){launch();return}e.status='Equilibrating';gseq.launching=true;gcEquilibrate();gseq.launching=false;function ready(){if(!gseq.active)return;if(gc.warming){gseq.timer=setTimeout(ready,100);return}if(!gc.ready||!gc.carrier||!gc.power){gcSequenceStop('Re-equilibration failed.');return}if(gcIsMS()){if(!gcDetectorReady()){gcSequenceStop('MS detector is not ready.');return}}else gc.flame=true;launch()}gseq.timer=setTimeout(ready,100);gcCalRefresh()}
function gcSequenceFinished(run){if(!gseq.active||run.sequenceEntry!==gseq.current)return;const e=gseq.queue.find(e=>e.id===gseq.current);if(run.calibrationError){e.status='Failed';gseq.active=false;gseq.message='Sequence stopped: '+run.calibrationError;gcCalRefresh();return}e.status='Complete';if(gcIsMS(run.method))run.saved=true;if(!run.saved){gc.history.push({method:{...run.method},sample:run.components.map(c=>({id:c.id,concentration:c.concentration})),peaks:run.peaks.map(p=>({...p})),acquired:run.duration,status:'Complete · vial '+run.calibration.id});gc.history=gc.history.slice(-8);run.saved=true;}gcSequenceSave();gseq.timer=setTimeout(()=>gcSequenceNext(),100)}
function gcSequenceStop(reason='Sequence stopped. Remaining injections stay pending.'){if(!gseq.active)return;gseq.active=false;clearTimeout(gseq.timer);const e=gseq.queue.find(e=>e.id===gseq.current);if(e&&['Running','Equilibrating'].includes(e.status))e.status='Stopped';if(gc.running||gc.paused)gcStop();else if(gc.warming){cancelAnimationFrame(gc.raf);gc.warming=false;gc.ready=false;gc.flame=false;}gseq.current=null;gseq.message=reason;gcCalRefresh()}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.gprepText&&!gcLocked()&&!gseq.active){gcal.form[t.dataset.gprepText]=t.value;gcCalSave()}if(t.dataset.gseqVolume&&!gseq.active){const row=gseq.queue.find(x=>x.id===Number(t.dataset.gseqVolume));if(row?.status==='Pending'){row.volume=Number(t.value);gcSequenceSave()}}});
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-gprep-solvent')&&!gcLocked()&&!gseq.active){gcal.form.solvent=e.target.value;gcCalRefresh()}});
document.addEventListener('click',e=>{const t=e.target,tab=t.closest('[data-gprep-tab]');if(tab){gcBenchTab=tab.dataset.gprepTab;try{localStorage.setItem('simlab-bench-tab',gcBenchTab)}catch{}go('bench');return}const action=t.closest('[data-gprep-action]')?.dataset.gprepAction;if(action==='bench'){gcBenchTab='gc';go('bench');return}if(action==='instrument'){go('instrumentation');return}if(action==='sequence-window'){const w=document.getElementById('gcSequenceWindow');if(w){gseq.open=true;w.open=true;w.scrollIntoView({block:'start',behavior:'auto'})}return}const seq=t.closest('[data-gseq-action]')?.dataset.gseqAction;if(seq==='stop'){gcSequenceStop();return}if(seq==='start'){gcSequenceStart();return}if(gseq.active||gcLocked())return;try{const exp=t.closest('[data-gprep-export]');if(exp){gcExportVial(Number(exp.dataset.gprepExport));gcCalRefresh();return}if(action==='export-all'){const fresh=gcal.vials.filter(v=>!v.exported);if(gseq.queue.length+fresh.length>60)throw Error('The sequence holds up to 60 injections. Remove finished entries first.');for(const v of fresh)gcExportVial(v.id);gcal.message=fresh.length?'Exported '+fresh.length+' vial(s) to GC. Open the instrument and set the sequence.':'All prepared vials are already exported. Use the individual button to add another injection.';}if(action==='load'){const id=Number(document.getElementById('gcPreparedSample')?.value);if(!id)throw Error('Choose an exported bench vial.');gcCalLoad(id);return}if(seq==='clear')gseq.queue=gseq.queue.filter(x=>!['Complete','Stopped','Failed','Interrupted'].includes(x.status));const up=t.closest('[data-gseq-up]'),remove=t.closest('[data-gseq-remove]'),repeat=t.closest('[data-gseq-repeat]');if(up){const i=gseq.queue.findIndex(x=>x.id===Number(up.dataset.gseqUp));if(i>0)[gseq.queue[i-1],gseq.queue[i]]=[gseq.queue[i],gseq.queue[i-1]];}if(remove)gseq.queue=gseq.queue.filter(x=>x.id!==Number(remove.dataset.gseqRemove));if(repeat){const row=gseq.queue.find(x=>x.id===Number(repeat.dataset.gseqRepeat));gcExportVial(row.vial);gseq.queue.at(-1).volume=row.volume;}if(action||seq||up||remove||repeat)gcCalRefresh();}catch(err){gseq.message=err.message;gcal.message=err.message;gcCalRefresh()}});

document.addEventListener('toggle',e=>{if(e.target.id==='gcSequenceWindow'&&e.target.isConnected)gseq.open=e.target.open},true);
